package com.jnapanam.sportszone.identity.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.jnapanam.sportszone.common.exception.*;import com.jnapanam.sportszone.identity.dto.RegisterRequest;import com.jnapanam.sportszone.notification.model.NotificationChannel;import com.jnapanam.sportszone.notification.service.NotificationService;import com.jnapanam.sportszone.notification.provider.NotificationProviderRegistry;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SmsOtpService{private final JdbcTemplate j;private final PasswordEncoder encoder;private final NotificationService notifications;private final ObjectMapper json;private final NotificationProviderRegistry providers;public SmsOtpService(JdbcTemplate j,PasswordEncoder e,NotificationService n,ObjectMapper json,NotificationProviderRegistry providers){this.j=j;encoder=e;notifications=n;this.json=json;this.providers=providers;}
 @Transactional public void registrationOtp(RegisterRequest r){String mobile=normalize(r.mobile());if(mobile==null)throw new BadRequestException("Mobile number is required for registration");issue(mobile,"REGISTRATION",write(r));}
 @Transactional public RegisterRequest verifyRegistration(String mobile,String otp){return read(verify(normalize(mobile),"REGISTRATION",otp),RegisterRequest.class);}
 @Transactional public void passwordResetOtp(String mobile){issue(normalize(mobile),"PASSWORD_RESET",null);}
 @Transactional public void verifyPasswordReset(String mobile,String otp){verify(normalize(mobile),"PASSWORD_RESET",otp);}
 private void issue(String mobile,String purpose,String payload){if(mobile==null)throw new BadRequestException("Mobile number is required");String otp=String.format("%06d",java.util.concurrent.ThreadLocalRandom.current().nextInt(1000000));j.update("insert into mobile_otp_challenges(id,purpose,mobile,otp_hash,payload_json,expires_at) values(?,?,?,?,?,?)",UUID.randomUUID(),purpose,mobile,encoder.encode(otp),payload,java.sql.Timestamp.from(Instant.now().plusSeconds(300)));providers.sms().sendOtp(mobile,otp);}
 private String verify(String mobile,String purpose,String otp){List<Map<String,Object>> rows=j.queryForList("select * from mobile_otp_challenges where mobile=? and purpose=? and verified_at is null order by created_at desc limit 1",mobile,purpose);if(rows.isEmpty())throw new BadRequestException("OTP not requested");Map<String,Object>x=rows.get(0);Instant exp=((java.sql.Timestamp)x.get("expires_at")).toInstant();if(Instant.now().isAfter(exp))throw new BadRequestException("OTP expired");int attempts=((Number)x.get("attempts")).intValue();if(attempts>=5)throw new BadRequestException("Too many OTP attempts");if(!encoder.matches(otp,(String)x.get("otp_hash"))){j.update("update mobile_otp_challenges set attempts=attempts+1 where id=?",x.get("id"));throw new BadRequestException("Invalid OTP");}j.update("update mobile_otp_challenges set verified_at=now() where id=?",x.get("id"));return (String)x.get("payload_json");}
 private UUID findUser(String mobile){List<UUID>x=j.query("select id from users where mobile=?", (rs,n)->UUID.fromString(rs.getString(1)),mobile);return x.isEmpty()?null:x.get(0);}private String normalize(String m){if(m==null)return null;String d=m.replaceAll("\\D","");return d.startsWith("91")&&d.length()==12?d.substring(2):d;}private String write(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}private <T>T read(String s,Class<T>t){try{return json.readValue(s,t);}catch(Exception e){throw new IllegalStateException(e);}}
}
